body.tpl-standard { font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, Roboto, sans-serif; font-size: 10px; color: #1e293b; margin: 0; padding: 12px; background-color: #ffffff; }
.tpl-standard .header-table { width: 100%; border-bottom: 2px solid {{ $accentColor ?: '#1e3a8a' }}; padding-bottom: 6px; margin-bottom: 12px; }
.tpl-standard .company-name { font-size: 15px; font-weight: 800; color: {{ $accentColor ?: '#1e3a8a' }}; text-transform: uppercase; }
.tpl-standard .company-address { font-size: 9px; color: #64748b; margin-top: 1px; }
.tpl-standard .payslip-title { font-size: 15px; font-weight: 800; color: {{ $accentColor ?: '#1e3a8a' }}; text-align: right; text-transform: uppercase; }
.tpl-standard .employee-info-table { width: 100%; background-color: #f8fafc; border: 1px solid #e2e8f0; border-collapse: collapse; margin-bottom: 12px; }
.tpl-standard .employee-info-table td { padding: 4.5px 8px; font-size: 9.5px; }
.tpl-standard .meta-label { color: #475569; font-weight: 600; }
.tpl-standard .meta-val { font-weight: 700; color: #0f172a; }
.tpl-standard .components-table { width: 100%; border-collapse: collapse; margin-bottom: 12px; }
.tpl-standard .components-table th { background-color: #f1f5f9; color: #0f172a; padding: 5px 7px; font-size: 9.5px; text-transform: uppercase; border: 1px solid #cbd5e1; font-weight: 700; }
.tpl-standard .components-table td { border: 1px solid #e2e8f0; padding: 4.5px 7px; font-size: 9.5px; }
.tpl-standard .net-pay-box { background-color: #f8fafc; border: 1px solid #cbd5e1; color: #0f172a; padding: 8px 12px; margin-bottom: 12px; border-left: 4px solid {{ $accentColor ?: '#1e3a8a' }}; }
.tpl-standard .net-amount { font-size: 14px; font-weight: 800; color: {{ $accentColor ?: '#1e3a8a' }}; }
.tpl-standard .net-words { font-size: 9px; font-style: italic; text-align: right; color: #334155; }
.tpl-standard .footer-note { text-align: center; font-size: 8px; color: #94a3b8; margin-top: 12px; border-top: 1px solid #e2e8f0; padding-top: 4px; }
